private static int decodeOctets(int i, ByteBuffer bb, StringBuilder sb) {
    if (bb == null || sb == null) {
        throw new IllegalArgumentException("ByteBuffer and StringBuilder must not be null");
    }
    if (!bb.hasRemaining()) {
        return i; // nothing to decode
    }

    try {
        int b0 = bb.get() & 0xFF;

        // ASCII
        if (b0 < 0x80) {
            sb.append((char) b0);
            return i + 1;
        }

        int bytesNeeded = 0;
        int mask = 0;

        if ((b0 & 0xE0) == 0xC0) {          // 110xxxxx
            bytesNeeded = 1;
            mask = 0x1F;
        } else if ((b0 & 0xF0) == 0xE0) {   // 1110xxxx
            bytesNeeded = 2;
            mask = 0x0F;
        } else if ((b0 & 0xF8) == 0xF0) {   // 11110xxx
            bytesNeeded = 3;
            mask = 0x07;
        } else { // invalid leading byte
            sb.append('\uFFFD');
            return i + 1;
        }

        if (bytesNeeded > 0) {
            if (bb.remaining() < bytesNeeded) {
                // incomplete sequence - treat as replacement character
                sb.append('\uFFFD');
                return i + 1;
            }

            long codePoint = b0 & mask;
            for (int j = 0; j < bytesNeeded; j++) {
                int nextByte = bb.get() & 0xFF;
                if ((nextByte & 0xC0) != 0x80) {
                    // invalid continuation byte
                    // Consume the bytes read so far and append replacement
                    sb.append('\uFFFD');
                    return i + 1;
                }
                codePoint = (codePoint << 6) | (nextByte & 0x3F);
            }

            if (codePoint > 0x10FFFF || (codePoint >= 0xD800 && codePoint <= 0xDFFF)) {
                // invalid code point
                sb.append('\uFFFD');
                return i + 1;
            }

            if (codePoint <= 0xFFFF) {
                sb.append((char) codePoint);
                return i + 1;
            } else {
                // surrogate pair
                codePoint -= 0x10000;
                char high = (char) ((codePoint >> 10) + 0xD800);
                char low = (char) ((codePoint & 0x3FF) + 0xDC00);
                sb.append(high).append(low);
                return i + 2;
            }
        }
    } catch (BufferUnderflowException e) {
        // Should not happen due to checks, but handle gracefully
        sb.append('\uFFFD');
        return i + 1;
    }

    // Fallback replacement
    sb.append('\uFFFD');
    return i + 1;
}

