private void enlarge(final int size){
    if (size <= 0) {
        return;
    }
    // If the underlying byte array is null, initialize it
    if (this.data == null) {
        this.data = new byte[size];
        this.capacity = size;
        return;
    }
    // If there is enough capacity already, no need to enlarge
    int remaining = this.capacity - this.length;
    if (remaining >= size) {
        return;
    }
    // Calculate new capacity (double or grow enough for the extra size)
    int newCap = Math.max(this.capacity * 2, this.length + size);
    if (newCap <= 0) { // guard against integer overflow
        newCap = Integer.MAX_VALUE;
    }
    byte[] newData = new byte[newCap];
    System.arraycopy(this.data, 0, newData, 0, this.length);
    this.data = newData;
    this.capacity = newCap;
}

protected static void deleteFile(String fileName) {
