        throw new RuntimeException("Permission denied while deleting file: " + fileName, se);
    }
}

public static int nullSafeHashCode(long[] array){
    if (array == null) {
        return 0;
    }
    int result = 1;
    for (long value : array) {
        int elementHash = (int)(value ^ (value >>> 32));
        result = 31 * result + elementHash;
    }
    return result;
}

private TreeNode<T> rotateRight(TreeNode<T> node){
    if(node == null){
        throw new IllegalArgumentException("node cannot be null");
    }
    TreeNode<T> left = node.getLeft();
    if(left == null){
        throw new IllegalArgumentException("left child cannot be null for right rotation");
    }
    // left subtree's right child becomes node's left child
    TreeNode<T> leftRight = left.getRight();
    left.setRight(node);
    node.setLeft(leftRight);
    return left;
}

@SuppressWarnings("unchecked") public static void addToClassPath(Vector<URL> cpV,String dir){
