                // ignore malformed jar URLs
                System.err.println("Malformed jar URL skipped: " + jar + " (" + e.getMessage() + ")");
            }
        }
    } catch (Exception e) {
        // generic handling for unexpected errors
        System.err.println("Error adding jars to classpath: " + e.getMessage());
        e.printStackTrace();
    }
}

public String format(LoggingEvent event){
