        throw new IllegalArgumentException("LoggingEvent cannot be null");
    }
    try {
        // Try to retrieve a formatted message if the method exists
        try {
            java.lang.reflect.Method method = event.getClass().getMethod("getFormattedMessage");
            Object result = method.invoke(event);
            if (result instanceof String) {
                return (String) result;
            }
        } catch (NoSuchMethodException | SecurityException | IllegalAccessException | IllegalArgumentException | java.lang.reflect.InvocationTargetException ignored) {
            // Method not available or inaccessible – fall back to toString()
        }
        // Fallback to the default toString() representation
        return event.toString();
    } catch (Exception e) {
        // Catch any unexpected exception and return a descriptive string
        return "ERROR formatting event: " + e.getMessage();
    }
}

