private int parseEndOfLine(String headerPart,int end){
    if(headerPart == null || headerPart.length() == 0) return -1;
    int len = headerPart.length();
    if(end < 0 || end >= len) return -1;
    for(int i = end; i < len - 1; i++){
        if(headerPart.charAt(i) == '\r' && headerPart.charAt(i + 1) == '\n'){
            return i;
        }
    }
    // If the last character is '\r' but there's no following '\n', it's incomplete
    return -1;
}

