@Override public void generateGraph(Graph<V, E> target, Map<String, V> resultMap) {
    if (target == null || resultMap == null) {
        return;
    }
    try {
        // Ensure all vertices from the result map are added to the graph
        for (V v : resultMap.values()) {
            if (!target.containsVertex(v)) {
                target.addVertex(v);
            }
        }

        // Partition vertices into two parts based on insertion order
        java.util.List<V> left = new java.util.ArrayList<>();
        java.util.List<V> right = new java.util.ArrayList<>();
        boolean toggle = true; // alternate assignment
        for (V v : resultMap.values()) {
            if (toggle) {
                left.add(v);
            } else {
                right.add(v);
            }
            toggle = !toggle;
        }

        // If one of the partitions is empty, attempt a fallback partitioning
        if (left.isEmpty() || right.isEmpty()) {
            java.util.Iterator<V> it = resultMap.values().iterator();
            if (it.hasNext()) {
                left.add(it.next());
            }
            if (it.hasNext()) {
                right.add(it.next());
            }
            while (it.hasNext()) {
                right.add(it.next());
            }
        }

        // If still one partition is empty, we cannot build a complete bipartite graph
        if (left.isEmpty() || right.isEmpty()) {
            return;
        }

        // Add all edges between the two partitions
        for (V u : left) {
            for (V v : right) {
                if (!target.containsEdge(u, v)) { // avoid duplicate edges if symmetric
                    target.addEdge(u, v);
                }
            }
        }
    } catch (IllegalArgumentException | UnsupportedOperationException e) {
        // Log or silently ignore issues with graph operations
        // e.g., if the graph does not support certain operations
    }
}

protected int findByte(byte value, int pos) {
    // Ensure the buffer exists.
    if (buffer == null) {
        return -1;
    }

    // Validate the starting position.
    if (pos < 0 || pos >= buffer.length) {
        return -1;
    }

    // Scan for the specified byte value from the starting position.
    for (int i = pos; i < buffer.length; i++) {
        if (buffer[i] == value) {
            return i;
        }
    }

    // Value not found.
    return -1;
}

public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    if (out == null) {
        throw new NullPointerException("Out");
    }
    if (message == null) {
        throw new NullPointerException("Message");
    }
    if (schema == null) {
        throw new NullPointerException("Schema");
    }
    int size = schema.computeSize(message);
    if (size < 0) {
        throw new IOException("Negative size");
    }
    // write size as varint
    int tmp = size;
    while ((tmp & ~0x7F) != 0) {
        out.write((tmp & 0x7F) | 0x80);
        tmp >>>= 7;
    }
    out.write(tmp);
    // write message to a temporary buffer and then forward to out
    ByteArrayOutputStream bos = new ByteArrayOutputStream(size);
    CodedOutputStream cos = CodedOutputStream.newInstance(bos);
    if (buffer == null) {
        buffer = LinkedBuffer.allocate(LinkedBuffer.DEFAULT_BUFFER_SIZE);
    }
    schema.writeTo(message, cos, buffer);
    cos.flush();
    bos.writeTo(out);
    return size;
}

