        throw new IllegalArgumentException("value cannot be null");
    }
    // The symbol table is assumed to have a field called `typeTable`
    // which stores the type symbols as a List<String> (or List<TypeSymbol>
    // where the `toString` representation equals the internal name).
    synchronized (this){
        for (int i = 0; i < typeTable.size(); i++){
            if (value.equals(typeTable.get(i))){
                return i; // type already present
            }
        }
        // add new type and return its new index
        typeTable.add(value);
        return typeTable.size() - 1;
    }
}

public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    if (genericType == null || targetType == null) {
        return null;
    }
    if (!(genericType instanceof ParameterizedType)) {
        return null;
    }
    ParameterizedType pt = (ParameterizedType) genericType;
    Class<?> raw = null;
    Type rawType = pt.getRawType();
    if (rawType instanceof Class<?>) {
        raw = (Class<?>) rawType;
    } else {
        return null;
    }
    // If raw type is not assignable from targetType, cannot resolve
    if (!raw.isAssignableFrom(targetType)) {
        return null;
    }
    Map<TypeVariable<?>, Type> typeVarAssigns = buildTypeVarAssignments(targetType, raw);
    if (typeVarAssigns == null) {
        return null;
    }
    Type[] args = pt.getActualTypeArguments();
    Class<?>[] result = new Class<?>[args.length];
    for (int i = 0; i < args.length; i++) {
        Type t = resolveType(args[i], typeVarAssigns);
        if (t instanceof Class<?>) {
            result[i] = (Class<?>) t;
        } else if (t instanceof ParameterizedType) { // use raw type
            Type r = ((ParameterizedType) t).getRawType();
            if (r instanceof Class<?>) {
                result[i] = (Class<?>) r;
            } else {
                return null;
            }
        } else {
            return null;
        }
    }
    return result;
}

@Override public void accept(final METRICS data){
    try {
        if (data == null) {
            return;
        }
        if (cache == null) {
            // Initialize cache if it hasn't been created yet.
            cache = new java.util.HashMap<>();
        }
        // Use a simple key that identifies the metric type.  This allows metrics of
        // the same type to be merged together.
        Object key = data.getClass().getName();
        METRICS existing = cache.get(key);
        if (existing == null) {
            cache.put(key, data);
        } else {
            // Try to merge using a possible `merge(METRICS)` method.
            try {
                java.lang.reflect.Method mergeMethod =
                        data.getClass().getMethod("merge", data.getClass());
                Object merged = mergeMethod.invoke(data, existing);
                if (merged instanceof METRICS) {
                    cache.put(key, (METRICS) merged);
                } else {
                    // If the merge returned void, it's assumed in-place modification.
                    cache.put(key, data);
                }
            } catch (NoSuchMethodException nsm) {
                // No merge method: replace the existing value.
                cache.put(key, data);
            } catch (Exception e) {
                // On merge failure, keep the existing value to avoid losing data.
                // Optionally log the error (not shown here).
            }
        }
    } catch (Exception e) {
        // General catch-all: ignore or log the exception, but do not throw further.
    }
}

