public long readLong(final int offset){
    if (offset < 0 || offset + 8 > this.data.length) {
        throw new IllegalArgumentException("Invalid long offset: " + offset);
    }
    final byte[] d = this.data;
    return ((long) (d[offset] & 0xFF) << 56) |
           ((long) (d[offset + 1] & 0xFF) << 48) |
           ((long) (d[offset + 2] & 0xFF) << 40) |
           ((long) (d[offset + 3] & 0xFF) << 32) |
           ((long) (d[offset + 4] & 0xFF) << 24) |
           ((long) (d[offset + 5] & 0xFF) << 16) |
           ((long) (d[offset + 6] & 0xFF) << 8) |
           ((long) (d[offset + 7] & 0xFF));
}

public boolean equals(final byte[] data, int offset, final int len) {
    // Validate parameters
    if (data == null) {
        return false;
    }
    if (offset < 0 || len < 0) {
        return false;
    }
    // Prevent integer overflow in bounds check
    if ((long) offset + len > data.length) {
        return false;
    }

    // Obtain the internal byte array (assumed to be named 'data' in the class)
    byte[] internal = this.data;
    if (internal == null) {
        return false;
    }
    if (internal.length != len) {
        return false;
    }

    // Compare byte by byte
    for (int i = 0; i < len; i++) {
        if (internal[i] != data[offset + i]) {
            return false;
        }
    }
    return true;
}

