public synchronized void send(final String message) {
    if (message == null) {
        return;
    }
    // Append CRLF to make it telnet-friendly
    final String telnetMessage = message + "\r\n";
    if (clients == null) {
        return;
    }
    for (Iterator<? extends PrintWriter> it = clients.iterator(); it.hasNext(); ) {
        PrintWriter out = it.next();
        try {
            out.print(telnetMessage);
            out.flush();
        } catch (Exception e) {
            // If sending fails, assume client disconnected and remove it
            it.remove();
        }
    }
}

