public void put(LoggingEvent o){
    if (o == null) {
        return; // nothing to insert
    }
    synchronized (this) {
        // Ensure buffer reference exists; drop silently if null
        if (buffer == null) {
            return;
        }
        // If buffer is full, silently drop the event
        if (size >= buffer.length) {
            return;
        }
        // Place the event at the current write index
        buffer[writeIndex] = o;
        // Update write index with wrap‑around
        writeIndex = (writeIndex + 1) % buffer.length;
        // Increment the count of stored events
        size++;
    }
}

protected List<TimeRange> buildTimeRanges(long start, long end) {
    if (start > end) {
        throw new IllegalArgumentException("Start time cannot be greater than end time");
    }
    List<TimeRange> ranges = new ArrayList<>();
    try {
        long current = start;
        while (current < end) {
            long next;
            if (current > Long.MAX_VALUE - FETCH_DATA_DURATION) {
                next = end;
            } else {
                next = Math.min(current + FETCH_DATA_DURATION, end);
            }
            ranges.add(new TimeRange(current, next));
            current = next;
        }
    } catch (Exception ex) {
        throw new RuntimeException("Error building time ranges", ex);
    }
    return ranges;
}

public static byte[] toPrimitive(final Byte[] array) {
