        Byte boxed = array[i];
        if (boxed == null) {
            throw new NullPointerException("array content at index " + i + " is null");
        }
        result[i] = boxed.byteValue();
    }
    return result;
}

static long compressTimeBucket(long timeBucket,int dayStep){
    if(dayStep <= 0){
        throw new IllegalArgumentException("dayStep must be positive");
    }
    String s = Long.toString(timeBucket);
    if(s.length() != 8){
        return timeBucket;
    }
    try{
        int year = Integer.parseInt(s.substring(0,4));
        int month = Integer.parseInt(s.substring(4,6));
        int day = Integer.parseInt(s.substring(6,8));
        java.time.LocalDate date = java.time.LocalDate.of(year, month, day);
        int dayOfYear = date.getDayOfYear();
        int bucketStartDayOfYear = ((dayOfYear - 1) / dayStep) * dayStep + 1;
        java.time.LocalDate bucketStartDate = java.time.LocalDate.ofYearDay(year, bucketStartDayOfYear);
        long yearPart = bucketStartDate.getYear() * 10000L;
        long monthPart = bucketStartDate.getMonthValue() * 100L;
        long dayPart = bucketStartDate.getDayOfMonth();
        return yearPart + monthPart + dayPart;
    }catch(RuntimeException e){
        // Covers DateTimeException, NumberFormatException
        return timeBucket;
    }
}

public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    if (str == null) {
        throw new IllegalArgumentException("String cannot be null");
    }
    if (index < 0 || len < 0) {
        throw new IllegalArgumentException("Index and length must be non‑negative");
    }
    int end = index + len;
    if (end > str.length()) {
        throw new IllegalArgumentException("Index + length exceeds string length");
    }

    int utf8Length = 0;
    for (int i = index; i < end; ) {
        char ch = str.charAt(i);
        int codePoint;

        // Check for surrogate pair
        if (Character.isHighSurrogate(ch)) {
            if (i + 1 < end) {
                char next = str.charAt(i + 1);
                if (Character.isLowSurrogate(next)) {
                    codePoint = Character.toCodePoint(ch, next);
                    i += 2;
                } else {
                    // Unpaired high surrogate: treat as replacement character
                    codePoint = 0xFFFD;
                    i += 1;
                }
            } else {
                // Unpaired high surrogate at end
                codePoint = 0xFFFD;
                i += 1;
            }
        } else if (Character.isLowSurrogate(ch)) {
            // Unpaired low surrogate: treat as replacement character
            codePoint = 0xFFFD;
            i += 1;
        } else {
            codePoint = ch;
            i += 1;
        }

        // Compute UTF‑8 byte length for this code point
        if (codePoint <= 0x7F) {
            utf8Length += 1;
        } else if (codePoint <= 0x7FF) {
            utf8Length += 2;
        } else if (codePoint <= 0xFFFF) {
            utf8Length += 3;
        } else {
            utf8Length += 4;
        }
    }
    return utf8Length;
}

