private Set<V> initVisibleVertices(){
    java.util.Set<V> visible = new java.util.HashSet<>();
    // Guard against null edge collection
    if (edges == null) {
        return visible;
    }
    for (Edge<V> edge : edges) {
        if (edge == null) {
            continue; // skip null edges
        }
        try {
            // Preferred: assume Edge exposes all incident vertices
            java.util.Collection<V> verts = edge.getVertices();
            if (verts != null) {
                for (V v : verts) {
                    if (v != null) {
                        visible.add(v);
                    }
                }
            }
        } catch (Exception e) {
            // Fallback: try common accessor names via reflection
            try {
                java.lang.reflect.Method m = edge.getClass().getMethod("getSource");
                @SuppressWarnings("unchecked")
                V src = (V) m.invoke(edge);
                if (src != null) {
                    visible.add(src);
                }
            } catch (Exception ignored) {}
            try {
                java.lang.reflect.Method m = edge.getClass().getMethod("getTarget");
                @SuppressWarnings("unchecked")
                V tgt = (V) m.invoke(edge);
                if (tgt != null) {
                    visible.add(tgt);
                }
            } catch (Exception ignored) {}
        }
    }
    return visible;
}

