public ByteVector putByteArray(final byte[] byteArrayValue, final int byteOffset, final int byteLength) {
    if (byteLength < 0) {
        throw new IllegalArgumentException("byteLength must be non-negative");
    }
    if (byteLength == 0) {
        return this;
    }
    if (byteArrayValue == null) {
        // add null bytes (zeroes)
        java.util.Arrays.fill(buffer, byteCount, byteCount + byteLength, (byte) 0);
        byteCount += byteLength;
        return this;
    }
    if (byteOffset < 0 || byteOffset > byteArrayValue.length) {
        throw new IndexOutOfBoundsException("byteOffset out of bounds");
    }
    if (byteOffset + byteLength > byteArrayValue.length) {
        throw new IndexOutOfBoundsException("byteOffset + byteLength exceeds array length");
    }
    int newSize = byteCount + byteLength;
    if (buffer.length < newSize) {
        int newCapacity = Math.max(buffer.length * 2, newSize);
        buffer = java.util.Arrays.copyOf(buffer, newCapacity);
    }
    java.lang.System.arraycopy(byteArrayValue, byteOffset, buffer, byteCount, byteLength);
    byteCount = newSize;
    return this;
}

public static AtmosphereRequest wrap(HttpServletRequest request){
