    }
    // Attempt to create a wrapper.  If AtmosphereRequest is a concrete class we can instantiate it directly.
    // If it is an interface or abstract class, this will throw a runtime exception which we propagate.
    try{
        return new AtmosphereRequest(request);
    }catch(Throwable t){
        // Fallback to a simple anonymous wrapper if the constructor is not public or doesn't exist
        return new AtmosphereRequest(){
            private final HttpServletRequest delegate = request;
            // All methods of AtmosphereRequest should delegate to the original request.
            // Since we cannot implement all methods here without knowing the interface, we
            // rethrow the original exception to help debugging.
