    }
    try {
        // Encode the string into UTF‑8 bytes
        byte[] utf8Bytes = str.toString().getBytes("UTF-8");
        // Append or write the bytes into the buffer
        try {
            // If LinkedBuffer behaves like an OutputStream
            lb.write(utf8Bytes);
        } catch (java.io.IOException e) {
            // In case the buffer does not support write(byte[]) directly
            // fallback to byte‑by‑byte write if such a method exists
            for (byte b : utf8Bytes) {
                try {
                    // Assume a writeByte or write method accepting a single byte
                    lb.write(b);
                } catch (java.io.IOException ex) {
                    throw new RuntimeException("Failed to write byte to LinkedBuffer", ex);
                }
            }
        }
    } catch (java.io.UnsupportedEncodingException e) {
        throw new RuntimeException("UTF-8 encoding not supported", e);
    }
    return lb;
}

public void removeFromTreeEdgeList(){
    // Safely unlink this edge from both doubly linked lists it belongs to.
    try {
        // First list
        if (prevTreeEdge != null) {
            prevTreeEdge.nextTreeEdge = nextTreeEdge;
        }
        if (nextTreeEdge != null) {
            nextTreeEdge.prevTreeEdge = prevTreeEdge;
        }

        // Second list
        if (prevTreeEdgeOpposite != null) {
            prevTreeEdgeOpposite.nextTreeEdgeOpposite = nextTreeEdgeOpposite;
        }
        if (nextTreeEdgeOpposite != null) {
            nextTreeEdgeOpposite.prevTreeEdgeOpposite = prevTreeEdgeOpposite;
        }

        // Help garbage collection by clearing references
        prevTreeEdge = null;
        nextTreeEdge = null;
        prevTreeEdgeOpposite = null;
        nextTreeEdgeOpposite = null;
    } catch (Exception e) {
        throw new RuntimeException("Failed to remove edge from tree edge lists", e);
    }
}

