private static boolean endsWith(final String str, final String suffix, final boolean ignoreCase) {
    // If both are null, return true
    if (str == null && suffix == null) {
        return true;
    }
    // If one is null but not both, return false
    if (str == null || suffix == null) {
        return false;
    }

    int strLen = str.length();
    int suffLen = suffix.length();

    // If suffix is longer than str, cannot be a suffix
    if (suffLen > strLen) {
        return false;
    }

    int startIndex = strLen - suffLen;
    if (ignoreCase) {
        // regionMatches with ignoreCase flag
        return str.regionMatches(true, startIndex, suffix, 0, suffLen);
    } else {
        // Perform direct comparison
        for (int i = 0; i < suffLen; i++) {
            if (str.charAt(startIndex + i) != suffix.charAt(i)) {
                return false;
            }
        }
        return true;
    }
}

public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    java.util.List<PathSegmentImpl> segments = new java.util.ArrayList<>();
    if (u == null) {
        return segments;
    }
    // Use raw path to preserve percent‑encoding
    String rawPath = u.getRawPath();
    if (rawPath == null || rawPath.isEmpty()) {
        return segments;
    }
    // If absolute (leading '/'), ignore leading slash for split purposes
    int startIndex = rawPath.startsWith("/") ? 1 : 0;
    int length = rawPath.length();
    int i = startIndex;
    while (i <= length) {
        int nextSlash = rawPath.indexOf('/', i);
        if (nextSlash == -1) {
            nextSlash = length;
        }
        String segmentRaw = rawPath.substring(i, nextSlash);
        String segmentDecoded = segmentRaw;
        if (decode) {
            try {
                segmentDecoded = java.net.URLDecoder.decode(segmentRaw, "UTF-8");
            } catch (Exception e) {
                // Fall back to raw segment if decoding fails
                segmentDecoded = segmentRaw;
            }
        }
        // Construct PathSegmentImpl – assumed constructor takes (String raw, String decoded)
        segments.add(new PathSegmentImpl(segmentRaw, segmentDecoded));
        i = nextSlash + 1;
    }
    return segments;
}

