public long readRawVarint64() throws IOException {
    long result = 0;
    int shift = 0;
    for (int i = 0; i < 10; i++) { // a varint long should be at most 10 bytes
        int b = input.read();
        if (b == -1) {
            throw new EOFException("Truncated varint: unexpected end of stream");
        }
        result |= (long)(b & 0x7F) << shift;
        if ((b & 0x80) == 0) {
            return result;
        }
        shift += 7;
    }
    throw new IOException("Malformed varint: longer than 10 bytes");
}

