private void pop(final String descriptor) {
    if (descriptor == null) {
        throw new IllegalArgumentException("descriptor cannot be null");
    }

    String args;
    int firstParen = descriptor.indexOf('(');
    if (firstParen != -1) {
        int endParen = descriptor.indexOf(')', firstParen);
        if (endParen == -1) {
            throw new IllegalArgumentException("invalid method descriptor: missing ')'");
        }
        args = descriptor.substring(firstParen + 1, endParen);
    } else {
        args = descriptor;
    }

    int i = 0;
    while (i < args.length()) {
        char c = args.charAt(i);
        int slots = 0;

        if (c == 'L') {
            // Object type: find terminating ';'
            int semicolon = args.indexOf(';', i);
            if (semicolon == -1) {
                throw new IllegalArgumentException("invalid object type descriptor");
            }
            slots = 1;
            i = semicolon + 1;
        } else if (c == '[') {
            // Array type: skip all '[' characters
            while (i < args.length() && args.charAt(i) == '[') {
                i++;
            }
            if (i >= args.length()) {
                throw new IllegalArgumentException("invalid array type descriptor");
            }
            char comp = args.charAt(i);
            if (comp == 'L') {
                int semicolon = args.indexOf(';', i);
                if (semicolon == -1) {
                    throw new IllegalArgumentException("invalid array object type descriptor");
                }
                i = semicolon + 1;
            } else {
                // Primitive component
                i++;
            }
            slots = 1;
        } else if (c == 'V') {
            // void – no slot to pop
            i++;
            continue;
        } else {
            // Primitive types
            switch (c) {
                case 'J': // long
                case 'D': // double
                    slots = 2;
                    break;
                case 'B': // byte
                case 'C': // char
                case 'S': // short
                case 'I': // int
                case 'Z': // boolean
                    slots = 1;
                    break;
                default:
                    throw new IllegalArgumentException("unknown type descriptor: " + c);
            }
            i++;
        }

        for (int s = 0; s < slots; s++) {
            if (output.isEmpty()) {
                throw new IllegalStateException("output frame stack underflow");
            }
            output.pop();
        }
    }
}

@Override public void write(final byte b[], final int off, final int len) throws IOException {
    if (b == null) {
        throw new NullPointerException("b is null");
    }
    if (off < 0 || len < 0 || off > b.length - len) {
        throw new IndexOutOfBoundsException("off=" + off + ", len=" + len + ", b.length=" + b.length);
    }
    if (len == 0) {
        return;
    }
    int newCount = count + len;
    if (newCount > buf.length) {
        int newSize = Math.max(buf.length << 1, newCount);
        byte newbuf[] = new byte[newSize];
        System.arraycopy(buf, 0, newbuf, 0, count);
        buf = newbuf;
    }
    System.arraycopy(b, off, buf, count, len);
    count = newCount;
}

public static final <V> void swap(V[] arr, int i, int j) {
    if (arr == null) {
        throw new IllegalArgumentException("Array cannot be null");
    }
    if (i < 0 || j < 0 || i >= arr.length || j >= arr.length) {
        throw new IllegalArgumentException("Index out of bounds");
    }
    if (i == j) {
        return;
    }
    V temp = arr[i];
    arr[i] = arr[j];
    arr[j] = temp;
}

public Boolean isPartialContentResponse(){
    try {
        // Try to find a field named "statusCode" or "status"
        java.lang.reflect.Field statusField = null;
        try {
            statusField = this.getClass().getDeclaredField("statusCode");
        } catch (NoSuchFieldException e) {
            try {
                statusField = this.getClass().getDeclaredField("status");
            } catch (NoSuchFieldException ex) {
                // Field not found, will try method next
            }
        }
        if (statusField != null) {
            statusField.setAccessible(true);
            Object val = statusField.get(this);
            if (val instanceof Number && ((Number) val).intValue() == 206) {
                return true;
            }
        }

        // If no suitable field, try a method named "getStatusCode" or "getCode"
        try {
            java.lang.reflect.Method getCodeMethod = this.getClass().getMethod("getStatusCode");
            Object res = getCodeMethod.invoke(this);
            if (res instanceof Number && ((Number) res).intValue() == 206) {
                return true;
            }
        } catch (NoSuchMethodException e) {
            try {
                java.lang.reflect.Method getCodeMethod = this.getClass().getMethod("getCode");
                Object res = getCodeMethod.invoke(this);
                if (res instanceof Number && ((Number) res).intValue() == 206) {
                    return true;
                }
            } catch (NoSuchMethodException ex) {
                // No method found, fallback to false
            }
        }

        // All attempts failed: not a partial content response
        return false;
    } catch (Exception e) {
        // Any reflection error or other exception leads to safe false
        return false;
    }
}

