        throw new IllegalArgumentException("sourceVertex, targetVertex, and e must not be null");
    }
    try {
        // Ensure the outer map contains the source vertex entry
        Map<V, Set<E>> targetMap = index.computeIfAbsent(sourceVertex, k -> new HashMap<>());
        // Ensure the inner map contains a set for the target vertex
        Set<E> edgeSet = targetMap.computeIfAbsent(targetVertex, k -> new HashSet<>());
        // Add the edge
        edgeSet.add(e);
    } catch (Exception ex) {
        throw new IllegalStateException("Failed to add edge to index", ex);
    }
}

private static File[] classPath(){
