public static Pair<Box2D,Box2D> splitAlongXAxis(Box2D box){
    if (box == null) {
        throw new IllegalArgumentException("box cannot be null");
    }
    // Extract the box extents, assuming getter methods exist
    double minX = box.getMinX();
    double maxX = box.getMaxX();
    double minY = box.getMinY();
    double maxY = box.getMaxY();
    // Validate dimensions
    if (minX > maxX || minY > maxY) {
        throw new IllegalArgumentException("Invalid box dimensions");
    }
    // Compute the vertical split point
    double midX = (minX + maxX) / 2.0;
    // Construct the two resulting boxes
    Box2D leftBox = new Box2D(minX, midX, minY, maxY);
    Box2D rightBox = new Box2D(midX, maxX, minY, maxY);
    // Return a Pair of the two boxes
    return new Pair<Box2D, Box2D>(leftBox, rightBox);
}

private void enlarge(final int size){
    if (size < 0) {
        throw new IllegalArgumentException("Size must be non-negative");
    }
    // Initialize buffer if necessary
    if (buf == null) {
        int initialCapacity = Math.max(16, size);
        buf = new byte[initialCapacity];
        return;
    }

    int required = pos + size;
    if (required <= buf.length) {
        // Current buffer is large enough
        return;
    }

    int newCapacity = Math.max(buf.length << 1, required);
    byte[] newBuf = new byte[newCapacity];
    System.arraycopy(buf, 0, newBuf, 0, pos);
    buf = newBuf;
}

