@Override public int compare(Double o1, Double o2) {
    try {
        if (o1 == null && o2 == null) {
            return 0;
        } else if (o1 == null) {
            return -1;
        } else if (o2 == null) {
            return 1;
        }
        double v1 = o1.doubleValue();
        double v2 = o2.doubleValue();
        if (Double.isNaN(v1) && Double.isNaN(v2)) {
            return 0;
        }
        if (Double.isNaN(v1)) {
            return 1; // NaN is treated as greater than any number
        }
        if (Double.isNaN(v2)) {
            return -1;
        }
        if (v1 < v2) {
            return -1;
        } else if (v1 > v2) {
            return 1;
        } else {
            return 0;
        }
    } catch (Exception e) {
        throw new IllegalArgumentException("Comparison failed: " + e.getMessage(), e);
    }
}

