private boolean containsAllFields(Fields fields){
    // Ensure the input and the backing property store are valid
    if (fields == null || properties == null) {
        return false;
    }
    try {
        // Iterate over the declared fields of the provided Fields object.
        // If any field name is not present in the properties map, return false.
        for (java.lang.reflect.Field f : fields.getClass().getDeclaredFields()) {
            if (!properties.containsKey(f.getName())) {
                return false;
            }
        }
    } catch (Exception e) {
        // Any reflective operation failure or missing key is treated as a non-match
        return false;
    }
    // All field names were found in the properties map
    return true;
}

