}

public static int writeTo(final DataOutput out, LinkedBuffer node) throws IOException {
    if (out == null) {
        throw new IllegalArgumentException("DataOutput cannot be null");
    }
    if (node == null) {
        return 0;
    }

    int totalSize = 0;
    LinkedBuffer current = node;
    while (current != null) {
        // Attempt to read fields that are most commonly used in LinkedBuffer implementations.
        // If any field is missing, the compiler will report an error and the implementation
        // can be adjusted accordingly.
        byte[] buffer;
        int size;
        LinkedBuffer next;

        try {
            buffer = current.buffer;      // usually a public field or accessible via getter
            size = current.size;          // usually the amount of valid data in the buffer
            next = current.next;          // next linked node
        } catch (NoSuchFieldError | NoSuchMethodError e) {
            throw new IllegalStateException("LinkedBuffer class does not expose expected fields", e);
        }

        if (buffer == null || size < 0 || size > buffer.length) {
            throw new IllegalStateException("LinkedBuffer contains invalid data");
        }

        out.write(buffer, 0, size);
        totalSize += size;
        current = next;
    }

    return totalSize;
}

