public String toString(){
    try {
        StringBuilder sb = new StringBuilder();
        sb.append('[');
        boolean first = true;
        java.util.Iterator<?> it = null;
        try {
            it = (java.util.Iterator<?>) this.getClass().getMethod("iterator").invoke(this);
        } catch (Exception ignored) {
        }
        if (it != null) {
            while (it.hasNext()) {
                Object o = it.next();
                if (!first) sb.append(", ");
                sb.append(String.valueOf(o));
                first = false;
            }
        } else {
            java.lang.reflect.Field f = null;
            java.lang.Object fieldValue = null;
            String[] candidateNames = {"items","data","queueArray","elements","array","values"};
            for (String name : candidateNames) {
                try {
                    f = this.getClass().getDeclaredField(name);
                    f.setAccessible(true);
                    fieldValue = f.get(this);
                    break;
                } catch (Exception e) {
                }
            }
            if (fieldValue != null) {
                if (fieldValue instanceof java.util.Collection) {
                    java.util.Collection<?> coll = (java.util.Collection<?>) fieldValue;
                    java.util.Iterator<?> itr = coll.iterator();
                    while (itr.hasNext()) {
                        Object o = itr.next();
                        if (!first) sb.append(", ");
                        sb.append(String.valueOf(o));
                        first = false;
                    }
                } else if (fieldValue.getClass().isArray()) {
                    int len = java.lang.reflect.Array.getLength(fieldValue);
                    for (int i = 0; i < len; i++) {
                        Object o = java.lang.reflect.Array.get(fieldValue, i);
                        if (!first) sb.append(", ");
                        sb.append(String.valueOf(o));
                        first = false;
                    }
                } else {
                    sb.append(String.valueOf(fieldValue));
                }
            } else {
                sb.append(super.toString());
            }
        }
        sb.append(']');
        return sb.toString();
    } catch (Exception e) {
        return "Error: " + e.getMessage();
    }
}

