public void readFrom(final InputStream in) throws IOException {
    if (in == null) {
        throw new IllegalArgumentException("InputStream cannot be null");
    }

    // Read all bytes from the input stream using a buffer.
    final int BUFFER_SIZE = 8192;
    byte[] temp = new byte[BUFFER_SIZE];
    int readCount;

    // Use a ByteArrayOutputStream to accumulate the data.
    try (ByteArrayOutputStream baos = new ByteArrayOutputStream()) {
        while ((readCount = in.read(temp)) != -1) {
            baos.write(temp, 0, readCount);
        }

        // Replace the existing buffer with the new data.
        this.buffer = baos.toByteArray();

        // Reset the read pointer to the beginning.
        this.readPointer = 0;
    } catch (IOException e) {
        // Rethrow the IOException as specified by the method signature.
        throw e;
    }
}

