@Override
protected Object convertToType(final Class<?> type, final Object value) throws Exception {
    // Ensure the target type is either java.lang.Character or the primitive char
    if (!Character.class.isAssignableFrom(type) && type != char.class) {
        throw new IllegalArgumentException("Target type must be Character or char");
    }

    // Handle null input
    if (value == null) {
        // Cannot return null for a primitive char
        if (type == char.class) {
            throw new IllegalArgumentException("Cannot return null for primitive char");
        }
        return null;
    }

    // Directly return if the value is already a Character
    if (value instanceof Character) {
        return value;
    }

    // Convert numeric types to a Character by casting the numeric value to char
    if (value instanceof Number) {
        int intVal = ((Number) value).intValue();
        return Character.valueOf((char) intVal);
    }

    // Convert a String of length 1 to a Character
    if (value instanceof String) {
        String str = (String) value;
        if (str.length() == 1) {
            return Character.valueOf(str.charAt(0));
        } else {
            throw new IllegalArgumentException("Cannot convert String of length > 1 to Character");
        }
    }

    // Unsupported conversion source type
    throw new IllegalArgumentException(
            "Unsupported conversion from " + value.getClass().getName() + " to Character");
}

public static boolean containsAnyIgnoreCase(String str, List<String> searchStrArray){
    if (str == null || searchStrArray == null) {
        return false;
    }
    String lowerStr = str.toLowerCase(java.util.Locale.ROOT);
    for (String search : searchStrArray) {
        if (search == null) {
            continue;
        }
        if (lowerStr.contains(search.toLowerCase(java.util.Locale.ROOT))) {
            return true;
        }
    }
    return false;
}

public static int nextPrime(int desiredCapacity) {
    if (desiredCapacity <= 2) {
        return 2;
    }
    int candidate = desiredCapacity;
    if (candidate % 2 == 0) {
        candidate++; // make it odd
    }

    while (candidate > 0) { // ensure no overflow
        if (isPrime(candidate)) {
            return candidate;
        }
        // Skip even numbers
        candidate += 2;
    }
    // fallback if no prime found (should not happen for int range)
    return Integer.MAX_VALUE;
}

