public static Object findFirstMatch(Collection source, Collection candidates){
    if (source == null || candidates == null) {
        return null;
    }
    try {
        for (Object candidate : candidates) {
            if (source.contains(candidate)) {
                return candidate;
            }
        }
    } catch (Exception e) {
        // Any exception during processing results in null return
        return null;
    }
    return null;
}

public static String trimTrailingWhitespace(String str){
    // Return null if input is null to avoid NullPointerException
    if (str == null) {
        return null;
    }
    int end = str.length();
    // Move backwards until a non-whitespace character is found
    while (end > 0 && Character.isWhitespace(str.charAt(end - 1))) {
        end--;
    }
    // Return the substring up to the trimmed index
    return str.substring(0, end);
}

