@Override public String readString() throws IOException {
    // Reads a string encoded as a 32-bit length prefix followed by UTF‑8 bytes.
    // A length of -1 represents a null value.
    int len = in.readInt();
    if (len == -1) {
        return null;
    }
    if (len < 0) {
        throw new IOException("Negative string length: " + len);
    }
    byte[] bytes = new byte[len];
    in.readFully(bytes);
    return new String(bytes, java.nio.charset.StandardCharsets.UTF_8);
}

private static int digitValue(final char c) {
    if (c >= '0' && c <= '9') {
        return c - '0';
    } else if (c >= 'A' && c <= 'Z') {
        return c - 'A' + 10;
    } else if (c >= 'a' && c <= 'z') {
        return c - 'a' + 10;
    } else {
        return -1; // non-ASCII digit
    }
}

private Map<String,Object> buildContent(JsonObject jsonObject){
    Map<String,Object> content = new HashMap<>();
    if (jsonObject == null) {
        return content;
    }
    try {
        for (String key : jsonObject.keySet()) {
            content.put(key, jsonObject.get(key));
        }
        // If the JSON contains an "ats" field, store it specially
        if (content.containsKey("ats")) {
            JsonElement atsElement = (JsonElement) content.get("ats");
            if (atsElement != null && atsElement.isJsonPrimitive()
                    && atsElement.getAsJsonPrimitive().isNumber()) {
                content.put("ats", atsElement.getAsJsonPrimitive().getAsLong());
            } else {
                content.put("ats", atsElement);
            }
        }
    } catch (Exception e) {
        throw new RuntimeException("Error building content from JsonObject", e);
    }
    return content;
}

