public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }
    StringBuilder sb = new StringBuilder(str.length());
    int len = str.length();
    for (int i = 0; i < len; i++) {
        char c = str.charAt(i);
        if (c != '\\') {
            sb.append(c);
            continue;
        }
        // backslash encountered; look ahead if possible
        if (i + 1 >= len) {
            sb.append('\\'); // trailing backslash stays as literal
            continue;
        }
        char next = str.charAt(i + 1);
        switch (next) {
            case 'b':
                sb.append('\b');
                i++;
                break;
            case 't':
                sb.append('\t');
                i++;
                break;
            case 'n':
                sb.append('\n');
                i++;
                break;
            case 'f':
                sb.append('\f');
                i++;
                break;
            case 'r':
                sb.append('\r');
                i++;
                break;
            case '\"':
                sb.append('\"');
                i++;
                break;
            case '\'':
                sb.append('\'');
                i++;
                break;
            case '\\':
                sb.append('\\');
                i++;
                break;
            case '0':
                sb.append('\0');
                i++;
                break;
            case 'u':
                // Unicode escape \uXXXX
                if (i + 5 >= len) {
                    throw new Exception("Malformed unicode escape sequence: " + str.substring(i));
                }
                String hex = str.substring(i + 2, i + 6);
                try {
                    int code = Integer.parseInt(hex, 16);
                    sb.append((char) code);
                } catch (NumberFormatException e) {
                    throw new Exception("Invalid unicode escape sequence: \\u" + hex);
                }
                i += 5; // skip \uXXXX
                break;
            default:
                if (next >= '0' && next <= '7') {
                    // Octal escape, up to 3 digits
                    int j = i + 1;
                    int digits = 1;
                    while (digits < 3 && j + 1 < len) {
                        char d = str.charAt(j + 1);
                        if (d >= '0' && d <= '7') {
                            digits++;
                            j++;
                        } else {
                            break;
                        }
                    }
                    String oct = str.substring(i + 1, i + 1 + digits);
                    try {
                        int val = Integer.parseInt(oct, 8);
                        sb.append((char) val);
                    } catch (NumberFormatException e) {
                        throw new Exception("Invalid octal escape sequence: \\" + oct);
                    }
                    i += digits; // skip used digits
                } else {
                    // Unrecognized escape, preserve the backslash
                    sb.append('\\');
                    sb.append(next);
                    i++; // skip next char
                }
                break;
        }
    }
    return sb.toString();
}

