public short readShort(final int offset){
    if (offset < 0 || offset + 1 >= this.b.length) {
        throw new IllegalArgumentException("offset out of bounds");
    }
    return (short)(((this.b[offset] & 0xFF) << 8) | (this.b[offset + 1] & 0xFF));
}

private static Object copyArrayGrow1(final Object array, final Class<?> newArrayComponentType) {
    // Validate input parameters
    if (array == null) {
        if (newArrayComponentType == null) {
            throw new IllegalArgumentException("Both array and newArrayComponentType cannot be null");
        }
        // Return a new array of length 1 with the specified component type
        return java.lang.reflect.Array.newInstance(newArrayComponentType, 1);
    }

    Class<?> arrayClass = array.getClass();
    if (!arrayClass.isArray()) {
        throw new IllegalArgumentException("The provided object is not an array: " + arrayClass.getName());
    }

    Class<?> componentType = arrayClass.getComponentType();
    int oldLength = java.lang.reflect.Array.getLength(array);
    Object newArray = java.lang.reflect.Array.newInstance(componentType, oldLength + 1);

    // Copy existing elements to the new array
    for (int i = 0; i < oldLength; i++) {
        java.lang.reflect.Array.set(newArray, i, java.lang.reflect.Array.get(array, i));
    }

    // The last element is left with the default value (null for object types, 0/false for primitives)
    return newArray;
}

private int computeBinaryLog(int n){
    if (n <= 0){
        throw new IllegalArgumentException("Input must be a positive integer");
    }
    int log2 = 31 - Integer.numberOfLeadingZeros(n);
    return log2 + 1;
}

private Set<V> intersection(Set<V> set1, Set<V> set2) {
    // Handle null inputs by returning an empty set
    if (set1 == null || set2 == null) {
        return new HashSet<>();
    }

    // If either set is empty, the intersection is empty
    if (set1.isEmpty() || set2.isEmpty()) {
        return new HashSet<>();
    }

    // Choose the smaller set to iterate over for efficiency
    Set<V> smaller = set1.size() <= set2.size() ? set1 : set2;
    Set<V> larger  = set1.size() <= set2.size() ? set2 : set1;

    Set<V> result = new HashSet<>(smaller.size());
    for (V element : smaller) {
        if (larger.contains(element)) {
            result.add(element);
        }
    }

    return result;
}

static String[] toNoNullStringArray(Collection<?> collection) {
    if (collection == null) {
        return new String[0];
    }
    List<String> result = new ArrayList<>();
    for (Object obj : collection) {
        if (obj != null) {
            result.add(obj.toString());
        }
    }
