final String readUtf(final int constantPoolEntryIndex,final char[] charBuffer){
    try{
        // Validate the index is within the constant pool bounds.
        if(constantPoolEntryIndex <= 0 || constantPoolEntryIndex >= this.constantPoolSize){
            throw new IndexOutOfBoundsException("Constant pool index out of bounds: "+constantPoolEntryIndex);
        }

        // Get the offset of the requested constant pool entry.
        int offset = this.constantPoolOffsets[constantPoolEntryIndex];
        if(offset < 0 || offset + 2 > this.classFileBuffer.length){
            throw new IllegalArgumentException("Invalid constant pool entry offset for index: "+constantPoolEntryIndex);
        }

        // The CONSTANT_Utf8 structure:
        //   u1 tag (already known to be 1) at offset
        //   u2 length at offset+1
        //   u1[<length>] bytes of modified UTF-8 at offset+3
        int length = ((this.classFileBuffer[offset + 1] & 0xFF) << 8) | (this.classFileBuffer[offset + 2] & 0xFF);
        if(length < 0 || offset + 3 + length > this.classFileBuffer.length){
            throw new IllegalArgumentException("Invalid UTF-8 string length for index: "+constantPoolEntryIndex);
        }

        // Decode the bytes using UTF-8 and return the resulting String.
        return new String(this.classFileBuffer, offset + 3, length, java.nio.charset.StandardCharsets.UTF_8);
    }catch(Exception e){
        // Wrap any exception in a runtime exception to preserve contract.
        throw new RuntimeException("Failed to read UTF-8 constant pool entry "+constantPoolEntryIndex, e);
    }
}

