public ByteVector putByteArray(final byte[] byteArrayValue,final int byteOffset,final int byteLength){
    // Validate length
    if (byteLength < 0) {
        throw new IllegalArgumentException("byteLength must be non‑negative");
    }
    // No source array – just append null bytes
    if (byteArrayValue == null) {
        if (byteLength == 0) {
            return this;
        }
        // Ensure capacity
        int required = used + byteLength;
        if (required > data.length) {
            int newCap = Math.max(data.length << 1, required);
            byte[] tmp = new byte[newCap];
            System.arraycopy(data, 0, tmp, 0, used);
            data = tmp;
        }
        // Fill with zeros
        for (int i = 0; i < byteLength; i++) {
            data[used++] = 0;
        }
        return this;
    }
    // Validate offset and bounds
    if (byteOffset < 0 || byteOffset > byteArrayValue.length - byteLength) {
        throw new IndexOutOfBoundsException("byteOffset or byteLength out of source array bounds");
    }
    if (byteLength == 0) {
        return this;
    }
    // Ensure capacity
    int required = used + byteLength;
    if (required > data.length) {
        int newCap = Math.max(data.length << 1, required);
        byte[] tmp = new byte[newCap];
        System.arraycopy(data, 0, tmp, 0, used);
        data = tmp;
    }
    // Copy bytes
    System.arraycopy(byteArrayValue, byteOffset, data, used, byteLength);
    used += byteLength;
    return this;
}

