private void check(String modelName) throws IllegalStateException {
    try {
        if (modelName == null || modelName.isEmpty()) {
            throw new IllegalStateException("Model name must not be null or empty");
        }
        // Retrieve the list of sharding key indices for the specified model.
        // The source of this list (e.g., a class field or method) should be provided by the implementing class.
        java.util.List<Integer> indices = shardingKeyIndicesMap.get(modelName);
        if (indices == null || indices.isEmpty()) {
            throw new IllegalStateException("No sharding key indices defined for model: " + modelName);
        }
        int min = Integer.MAX_VALUE;
        int max = Integer.MIN_VALUE;
        java.util.Set<Integer> unique = new java.util.HashSet<>();
        for (Integer idx : indices) {
            if (idx == null) {
                throw new IllegalStateException("Sharding key index cannot be null for model: " + modelName);
            }
            if (idx < min) {
                min = idx;
            }
            if (idx > max) {
                max = idx;
            }
            if (!unique.add(idx)) {
                throw new IllegalStateException("Duplicate sharding key index " + idx + " for model: " + modelName);
            }
        }
        if (max - min + 1 != indices.size()) {
            throw new IllegalStateException("Sharding key indices for model " + modelName + " are not continuous");
        }
        for (int i = min; i <= max; i++) {
            if (!unique.contains(i)) {
                throw new IllegalStateException("Sharding key indices for model " + modelName + " are not continuous; missing index: " + i);
            }
        }
    } catch (IllegalStateException e) {
        throw e;
    } catch (Exception e) {
        throw new IllegalStateException("Failed to check sharding key indices for model " + modelName + ": " + e.getMessage(), e);
    }
}

