        for (V vertex : v) {
            // Assuming the graph has a map of incoming edges keyed by vertex
            Set<Edge<V>> edges = this.incomingEdges.get(vertex);
            if (edges != null) {
                for (Edge<V> edge : edges) {
                    if (edge != null) {
                        Double w = edge.getWeight();
                        if (w != null) {
                            sum += w;
                        }
                    }
                }
            }
        }
    } catch (Exception e) {
        // In case of any runtime issues, return the sum computed so far
    }
    return sum;
}

public int compare(Object aObj1, Object aObj2){
    if (aObj1 == aObj2) {
