    }
    if (aObj2 == null) {
        return 1;  // non-null is greater
    }
    if (aObj1 instanceof Comparable && aObj2 instanceof Comparable) {
        try {
            @SuppressWarnings("unchecked")
            Comparable<Object> c1 = (Comparable<Object>) aObj1;
            return c1.compareTo(aObj2);
        } catch (ClassCastException e) {
            throw new ClassCastException("Objects are not mutually comparable");
        }
    } else {
        throw new ClassCastException("Objects are not comparable");
    }
}

