    }
    boolean removed = false;
    try {
        Iterator<Appender> it = appenders.iterator();
        while (it.hasNext()){
            Appender app = it.next();
            if (name.equals(app.getName())){
                it.remove();
                removed = true;
                break;
            }
        }
    } catch (Exception e){
