        return count;
    }
    try {
        java.util.Enumeration<?> enums = getAllAppenders();
        if (enums == null) {
            return count;
        }
        while (enums.hasMoreElements()) {
            Object obj = enums.nextElement();
            try {
                ((org.apache.log4j.Appender)obj).doAppend(event);
                count++;
            } catch (Throwable t) {
                // Silently ignore errors from individual appenders
            }
        }
    } catch (Throwable t) {
        // Fail safe: return the number of successfully processed appenders
    }
    return count;
}

