protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    if (graph == null) {
        throw new IllegalArgumentException("Graph must not be null");
    }
    if (tour == null) {
        throw new IllegalArgumentException("Tour set must not be null");
    }
    if (tour.isEmpty()) {
        // return an empty path
        return new org.jgrapht.graph.DefaultGraphPath<>(graph,
                java.util.Collections.emptyList(),
                java.util.Collections.emptyList(),
                0,
                0.0);
    }

    // Validate that all edges belong to the graph
    for (E e : tour) {
        if (!graph.containsEdge(e)) {
            throw new IllegalArgumentException("Edge " + e + " is not in the graph");
        }
    }

    // Start with an arbitrary edge
    E startEdge = tour.iterator().next();
    V startVertex;
    if (graph.getType().isDirected()) {
        startVertex = graph.getEdgeSource(startEdge);
    } else {
        // For undirected graphs, choose any endpoint
        startVertex = graph.getEdgeSource(startEdge);
    }

    java.util.Set<E> remaining = new java.util.HashSet<>(tour);
    java.util.List<V> vertexList = new java.util.ArrayList<>();
    java.util.List<E> edgeList = new java.util.ArrayList<>();

    V current = startVertex;
    vertexList.add(current);

    double totalWeight = 0.0;

    while (!remaining.isEmpty()) {
        E nextEdge = null;
        for (E e : remaining) {
            if (graph.getType().isDirected()) {
                if (graph.getEdgeSource(e).equals(current)) {
                    nextEdge = e;
                    break;
                }
            } else {
                if (graph.getEdgeSource(e).equals(current) || graph.getEdgeTarget(e).equals(current)) {
                    nextEdge = e;
                    break;
                }
            }
        }
        if (nextEdge == null) {
            // Cannot extend path with remaining edges; break to avoid infinite loop
            break;
        }

        remaining.remove(nextEdge);
        edgeList.add(nextEdge);
        totalWeight += graph.getEdgeWeight(nextEdge);

        V nextVertex = graph.getEdgeSource(nextEdge).equals(current)
                ? graph.getEdgeTarget(nextEdge)
                : graph.getEdgeSource(nextEdge);
        current = nextVertex;
        vertexList.add(current);
    }

    // If after traversal some edges remain, we cannot construct a full tour
    if (!remaining.isEmpty()) {
        throw new IllegalArgumentException("Provided edges do not form a connected tour");
    }

    return new org.jgrapht.graph.DefaultGraphPath<>(graph,
            vertexList,
            edgeList,
            edgeList.size(),
            totalWeight);
}

