int addConstantNameAndType(final String name, final String descriptor) {
    if (name == null || descriptor == null) {
        throw new IllegalArgumentException("Name and descriptor must not be null");
    }
    try {
        // Use a simple key to search for an existing entry
        final String key = name + "#" + descriptor;
        // Assume a map is maintained for quick lookup
        Integer existingIndex = this.nameAndTypeIndexMap.get(key);
        if (existingIndex != null) {
            return existingIndex;
        }

        // Add UTF-8 constants for the name and descriptor if they don't exist yet
        int nameIndex = this.addUtf8Constant(name);
        int descriptorIndex = this.addUtf8Constant(descriptor);

        // Create a new constant pool entry for NameAndType
        int newIndex = this.constantPool.size();
        this.constantPool.add(new NameAndTypeInfo(nameIndex, descriptorIndex));

        // Store the index for future lookup
        this.nameAndTypeIndexMap.put(key, newIndex);

        return newIndex;
    } catch (Exception e) {
        throw new RuntimeException("Failed to add CONSTANT_NameAndType_info", e);
    }
}

private String unescapeId(String input){
    if (input == null){
        return null;
    }
    StringBuilder sb = new StringBuilder(input.length());
    boolean escaped = false;
    for (int i = 0; i < input.length(); i++){
        char ch = input.charAt(i);
        if (escaped){
            switch (ch){
                case 'n': sb.append('\n'); break;
                case 'r': sb.append('\r'); break;
                case 't': sb.append('\t'); break;
                case '\\': sb.append('\\'); break;
                case '"': sb.append('"'); break;
                case '\'' : sb.append('\''); break;
                case 'b': sb.append('\b'); break;
                case 'f': sb.append('\f'); break;
                default: sb.append(ch); break;
            }
            escaped = false;
        } else if (ch == '\\'){
            escaped = true;
        } else {
            sb.append(ch);
        }
    }
    // In case the string ends with a single backslash, treat it as a literal backslash
    if (escaped){
        sb.append('\\');
    }
    return sb.toString();
}

