void removeSelf() {
    try {
        // Ensure the bucket belongs to a container
        if (owner == null) {
            throw new IllegalStateException("Bucket is not part of any container");
        }
        // Re-link adjacent buckets
        if (prev != null) {
            prev.next = next;
        } else {
            owner.firstBucket = next;
        }
        if (next != null) {
            next.prev = prev;
        } else {
            owner.lastBucket = prev;
        }
        // Update container bookkeeping
        if (owner.bucketCount > 0) {
            owner.bucketCount--;
        }
        // Clean up this bucket's references
        prev = null;
        next = null;
        owner = null;
    } catch (Exception e) {
        throw new RuntimeException("Failed to remove bucket", e);
    }
}

