    try {
        ListNodeImpl<E> prev = node.prev;
        ListNodeImpl<E> next = node.next;

        if (prev != null) {
            prev.next = next;
        } else {
            // node was the head
            head = next;
        }

        if (next != null) {
            next.prev = prev;
        } else {
            // node was the tail
            tail = prev;
        }

        // Detach the node
        node.prev = null;
        node.next = null;

        if (size > 0) {
            size--;
        }
        return true;
    } catch (Exception e) {
        // In case of any unexpected issues, return false
        return false;
    }
}

