public static String stripFilenameExtension(String path) {
    if (path == null) {
        return null;
    }
    int lastSeparator = Math.max(path.lastIndexOf('/'), path.lastIndexOf('\\'));
    int lastDot = path.lastIndexOf('.');
    // No dot or dot comes before the last file separator
    if (lastDot == -1 || lastDot <= lastSeparator) {
        return null;
    }
    // No characters after the dot (empty extension) or dot immediately follows separator
    if (lastDot == path.length() - 1 || lastDot <= lastSeparator + 1) {
        return null;
    }
    return path.substring(0, lastDot);
}

