private String parseToken(final char[] terminators) {
    StringBuilder sb = new StringBuilder();

    // If no terminators are provided, consume the rest of the stream
    if (terminators == null || terminators.length == 0) {
        try {
            int ch;
            while ((ch = reader.read()) != -1) {
                sb.append((char) ch);
            }
        } catch (java.io.IOException e) {
            throw new RuntimeException("Failed to parse token", e);
        }
        return sb.toString();
    }

    // Read characters until one of the terminators is encountered or EOF
    try {
        int ch;
        while ((ch = reader.read()) != -1) {
            char c = (char) ch;
            boolean isTerminator = false;
            for (char t : terminators) {
                if (c == t) {
                    isTerminator = true;
                    break;
                }
            }
            if (isTerminator) {
                break;  // stop before appending the terminator
            }
            sb.append(c);
        }
    } catch (java.io.IOException e) {
        throw new RuntimeException("Failed to parse token", e);
    }

    return sb.toString();
}

