private Pair<List<Integer>,Long> computeSuffixSum(List<Integer> bounds){
    // Handle null or empty input gracefully
    if (bounds == null || bounds.isEmpty()){
        // Return empty list and zero sum
        return new Pair<>(Collections.emptyList(), 0L);
    }
    int n = bounds.size();
    List<Integer> suffixSumList = new ArrayList<>(n);
    long totalSum = 0;
    long suffixSum = 0;
    // Compute suffix sums from the end towards the front
    for (int i = n - 1; i >= 0; i--) {
        suffixSum += bounds.get(i);
        // Casting to int matches the declared List<Integer> type; 
        // For safety, we cap at Integer.MAX_VALUE/Integer.MIN_VALUE if overflow occurs
        if (suffixSum > Integer.MAX_VALUE) suffixSum = Integer.MAX_VALUE;
        if (suffixSum < Integer.MIN_VALUE) suffixSum = Integer.MIN_VALUE;
        suffixSumList.add(0, (int) suffixSum);
    }
    totalSum = suffixSumList.isEmpty() ? 0 : suffixSumList.get(0) + suffixSumList.size() > 0 ? (long) suffixSumList.get(0) : 0;
    // Compute overall sum separately to avoid accidental overflow
    totalSum = 0;
    for (int val : bounds) {
        totalSum += val;
    }
    return new Pair<>(suffixSumList, totalSum);
}

public static final <V> void reverse(V[] arr, int from, int to) {
    if (arr == null) {
        throw new IllegalArgumentException("Array must not be null");
    }
    int len = arr.length;
    if (len == 0) {
        throw new IllegalArgumentException("Array is empty; range indices invalid");
    }
    if (from < 0 || to >= len || from > to) {
        throw new IllegalArgumentException(
            "Invalid range: from=" + from + ", to=" + to + ", array length=" + len);
    }
    int i = from;
    int j = to;
    while (i < j) {
        V temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
        i++;
        j--;
    }
}

private void moveAllListNodes(DoublyLinkedList<E> list) {
    // Guard against null argument
    if (list == null) {
        throw new NullPointerException("The source list cannot be null.");
    }

    // If the source and destination are the same list, nothing to do
    if (list == this) {
        return;
    }

    try {
        // Keep moving the first node until the source list is empty
        while (!list.isEmpty()) {
            // Grab the first node from the source list
            ListNodeImpl<E> node = list.getFirst();
            if (node == null) {
                // Safety check: break if getting first failed
                break;
            }

            // Remove the node from its current list
            list.removeListNode(node);
            // Add the node to this list
            this.addListNode(node);
        }
    } catch (RuntimeException e) {
        // If something unexpected happens we rethrow as an unchecked exception
        throw new IllegalStateException("Failed to move all nodes atomically.", e);
    }
}

private static boolean startsWith(final String str, final String prefix, final boolean ignoreCase) {
    // Handle nulls first
    if (str == null) {
        return prefix == null;            // true only if both are null
    }
    if (prefix == null) {
        return true;                       // any string starts with a null prefix
    }

    // If ignoreCase flag is set, compare substring with prefix ignoring case
    if (ignoreCase) {
        if (prefix.length() > str.length()) {
            return false;
        }
        return str.substring(0, prefix.length()).equalsIgnoreCase(prefix);
    }

    // Normal case-sensitive comparison
    return str.startsWith(prefix);
}

