public void abbreviate(final int nameStart, final StringBuffer buf){
    // Validate inputs
    if (buf == null) {
        throw new IllegalArgumentException("buf cannot be null");
    }
    if (nameStart < 0 || nameStart > buf.length()) {
        throw new IllegalArgumentException("nameStart out of bounds");
    }

    String original = buf.toString();
    String prefix = original.substring(0, nameStart);

    StringBuilder abbreviated = new StringBuilder();
    int idx = nameStart;

    // Skip any leading whitespace from the start position
    while (idx < original.length() && Character.isWhitespace(original.charAt(idx))) {
        idx++;
    }

    // Build abbreviation for the rest of the string
    while (idx < original.length()) {
        int wordStart = idx;
        while (idx < original.length() && !Character.isWhitespace(original.charAt(idx))) {
            idx++;
        }
        String word = original.substring(wordStart, idx);
        if (!word.isEmpty()) {
            if (word.length() > 1) {
                abbreviated.append(word.charAt(0)).append('.');
            } else {
                abbreviated.append(word);
            }
        }
        // Append a space if there's more to process
        if (idx < original.length()) {
            abbreviated.append(' ');
        }
        // Skip whitespace before next word
        while (idx < original.length() && Character.isWhitespace(original.charAt(idx))) {
            idx++;
        }
    }

    // Preserve any prefix that was before nameStart
    StringBuilder result = new StringBuilder(prefix);
    if (prefix.length() > 0 && abbreviated.length() > 0) {
        result.append(' ');
    }
    result.append(abbreviated);

    // Replace the content of the buffer with the abbreviation
    buf.setLength(0);
    buf.append(result.toString());
}

