private static <V, E> boolean isClique(Graph<V, E> graph, Set<V> vertices) {
    if (graph == null || vertices == null) {
        throw new IllegalArgumentException("Graph and vertices set must not be null.");
    }
    int size = vertices.size();
    if (size < 2) {
        return true; // Empty or single-vertex sets are trivially cliques.
    }
    try {
        List<V> list = new ArrayList<>(vertices);
        for (int i = 0; i < size; i++) {
            V vi = list.get(i);
            for (int j = i + 1; j < size; j++) {
                V vj = list.get(j);
                if (!graph.containsEdge(vi, vj)) {
                    return false;
                }
            }
        }
        return true;
    } catch (Exception e) {
        throw new IllegalArgumentException("Error checking clique status due to invalid graph or vertices.", e);
    }
}

private List<Integer> computeLowerBounds(List<K> keys){
    // Handle null or empty input
    if (keys == null) {
        throw new IllegalArgumentException("Input key list must not be null");
    }
    List<Integer> lowerBounds = new ArrayList<>(keys.size());
    // For each key, compute the maximum lower bound among all keys
    for (K key : keys) {
        int keyValue;
        // Try to convert the key to an integer value
        if (key instanceof Number) {
            keyValue = ((Number) key).intValue();
        } else {
            // Cannot determine numeric value; set a sentinel and continue
            lowerBounds.add(Integer.MIN_VALUE);
            continue;
        }
        int maxLower = Integer.MIN_VALUE;
        for (K other : keys) {
            if (other == key) {
                continue;
            }
            if (other instanceof Number) {
                int otherVal = ((Number) other).intValue();
                if (otherVal < keyValue && otherVal > maxLower) {
                    maxLower = otherVal;
                }
            }
        }
        lowerBounds.add(maxLower);
    }
    return lowerBounds;
}

private void pop(final String descriptor) {
    if (descriptor == null) {
        throw new IllegalArgumentException("Descriptor must not be null");
    }
    final int len = descriptor.length();
    if (len == 0) {
        throw new IllegalArgumentException("Empty descriptor");
    }

    // Helper to pop one slot
    Runnable popOne = () -> outputStack.pop();

    // Helper to pop a type that may take two slots (J or D)
    java.util.function.Consumer<Character> popType = c -> {
        if (c == 'J' || c == 'D') {
            outputStack.pop();
            outputStack.pop();
        } else {
            outputStack.pop();
        }
    };

    int i = 0;
    if (descriptor.charAt(0) == '(') {
        // Method descriptor: pop all argument types
        int close = descriptor.indexOf(')', 1);
        if (close == -1) {
            throw new IllegalArgumentException("Invalid method descriptor: " + descriptor);
        }

        i = 1;
        while (i < close) {
            char c = descriptor.charAt(i);
            if (c == 'L') {
                // Object type L...;
                int end = descriptor.indexOf(';', i);
                if (end == -1) {
                    throw new IllegalArgumentException("Invalid object type descriptor: " + descriptor);
                }
                popOne.run();
                i = end + 1;
            } else if (c == '[') {
                // Array type: skip all '['
                while (i < close && descriptor.charAt(i) == '[') {
                    i++;
                }
                if (i >= close) {
                    throw new IllegalArgumentException("Invalid array descriptor: " + descriptor);
                }
                if (descriptor.charAt(i) == 'L') {
                    int end = descriptor.indexOf(';', i);
                    if (end == -1) {
                        throw new IllegalArgumentException("Invalid object array descriptor: " + descriptor);
                    }
                    i = end + 1;
                } else {
                    // primitive component
                    i++; // move past primitive specifier
                }
                popOne.run();
            } else {
                // Primitive type
                popType.accept(c);
                i++;
            }
        }
    } else {
        // Type descriptor: pop one (or two) value
        char c = descriptor.charAt(0);
        if (c == 'L') {
            if (!descriptor.endsWith(";")) {
                throw new IllegalArgumentException("Invalid object type descriptor: " + descriptor);
            }
            popOne.run();
        } else if (c == '[') {
            int j = 0;
            while (j < len && descriptor.charAt(j) == '[') {
                j++;
            }
            if (j >= len) {
                throw new IllegalArgumentException("Invalid array descriptor: " + descriptor);
            }
            if (descriptor.charAt(j) == 'L') {
                int end = descriptor.indexOf(';', j);
                if (end == -1) {
                    throw new IllegalArgumentException("Invalid object array descriptor: " + descriptor);
                }
            } else {
                // Primitive inside array, validate
                char p = descriptor.charAt(j);
                if ("ZBCSIFJD".indexOf(p) == -1) {
                    throw new IllegalArgumentException("Invalid array component in descriptor: " + descriptor);
                }
            }
            popOne.run();
        } else {
            // Primitive type
            popType.accept(c);
        }
    }
}

