private List<Integer> computeUpperBounds(List<K> keys){
    List<Integer> bounds = new java.util.ArrayList<>();
    if(keys == null){
        return bounds;
    }
    for (K key : keys){
        int boundValue;
        if (key == null){
            boundValue = 0;
        } else {
            try {
                if (key instanceof Integer) {
                    boundValue = (Integer) key;
                } else if (key instanceof Number) {
                    boundValue = ((Number) key).intValue();
                } else {
                    // Try to parse an integer from the key's string representation
                    boundValue = Integer.parseInt(key.toString());
                }
            } catch (Exception e) {
                // If anything goes wrong, default to 0
                boundValue = 0;
            }
        }
        // The “upper bound” here is taken as the key value plus one
        bounds.add(boundValue + 1);
    }
    return bounds;
}

public static String encodeTemplateNames(String s) {
    if (s == null) {
        return null;
    }
    try {
        // Replace “{” and “}” with their percent-encoded equivalents
        return s.replace("{", "%7B").replace("}", "%7D");
    } catch (Exception e) {
        // In case of unexpected errors, return the original string
        return s;
    }
}

public static boolean equals(Point2D p1, Point2D p2) {
    if (p1 == null && p2 == null) {
        return true;
    }
    if (p1 == null || p2 == null) {
        return false;
    }
    final double eps = 1e-9;
    double dx = p1.getX() - p2.getX();
    if (Math.abs(dx) > eps) {
        return false;
    }
    double dy = p1.getY() - p2.getY();
    return Math.abs(dy) <= eps;
}

