}

public static String applyRelativePath(String path, String relativePath) {
    try {
        // Handle null or empty inputs
        if (relativePath == null || relativePath.isEmpty()) {
            return path == null ? "" : path;
        }
        if (path == null) {
            path = "";
        }

        // Determine if the relativePath is absolute (starts with '/' or a drive letter)
        String relPrefix = "";
        String relative = relativePath;
        if (relative.startsWith("/")) {
            relPrefix = "/";
            relative = relative.substring(1);
        } else if (relative.length() > 1 && Character.isLetter(relative.charAt(0))
                && relative.charAt(1) == ':') {
            relPrefix = relative.substring(0, 2); // e.g., "C:"
            if (relative.length() > 2 && relative.charAt(2) == '/') {
                relPrefix += "/";
                relative = relative.substring(3);
            } else {
                relative = relative.substring(2);
            }
        } else {
            // Leave relPrefix empty for a relative path
        }

        // If the path is relative, preserve any leading '/' or drive letter from the base path
        String basePrefix = "";
        String base = path;
        if (!base.isEmpty()) {
            if (base.startsWith("/")) {
                basePrefix = "/";
                base = base.substring(1);
            } else if (base.length() > 1 && Character.isLetter(base.charAt(0))
                    && base.charAt(1) == ':') {
                basePrefix = base.substring(0, 2); // e.g., "C:"
                if (base.length() > 2 && base.charAt(2) == '/') {
                    basePrefix += "/";
                    base = base.substring(3);
                } else {
                    base = base.substring(2);
                }
            } else {
                // relative base path; prefix remains empty
            }
        }

        // Build a stack of path components
        java.util.ArrayDeque<String> stack = new java.util.ArrayDeque<>();

        // Add base components to the stack
        if (!base.isEmpty()) {
            for (String part : base.split("/")) {
                if (part.isEmpty() || part.equals(".")) {
                    continue;
                }
                if (part.equals("..")) {
                    if (!stack.isEmpty()) {
                        stack.removeLast();
                    }
                } else {
                    stack.addLast(part);
                }
            }
        }

        // If the relative path is absolute, ignore the base stack
        if (!relPrefix.isEmpty()) {
            stack.clear();
        }

        // Process relative components
        for (String part : relative.split("/")) {
            if (part.isEmpty() || part.equals(".")) {
                continue;
            }
            if (part.equals("..")) {
                if (!stack.isEmpty()) {
                    stack.removeLast();
                }
            } else {
                stack.addLast(part);
            }
        }

        // Reconstruct the combined path
        StringBuilder result = new StringBuilder();
        if (!relPrefix.isEmpty()) {
            result.append(relPrefix);
        } else if (!basePrefix.isEmpty() && stack.isEmpty()) {
            // Preserve a trailing slash for the root if no components
            result.append(basePrefix);
        }

        java.util.Iterator<String> it = stack.iterator();
        while (it.hasNext()) {
            result.append(it.next());
            if (it.hasNext()) {
                result.append('/');
            }
        }

        // Handle case where result is empty but we had a prefix (e.g., root "/")
        if (result.length() == 0 && !relPrefix.isEmpty()) {
            result.append(relPrefix).append("/");
        }

        return result.toString();
    } catch (Exception e) {
        // In case of any unexpected error, fall back to the input path
        return path == null ? "" : path;
    }
}

