static String[] toNoNullStringArray(Object[] array){
    try {
        if (array == null) {
            return new String[0];
        }
        java.util.ArrayList<String> result = new java.util.ArrayList<>();
        for (Object obj : array) {
            if (obj != null) {
                result.add(String.valueOf(obj));
            }
        }
        return result.toArray(new String[0]);
    } catch (Exception e) {
        throw new IllegalArgumentException("Failed to normalize string array", e);
    }
}

public static int indexOfExtension(String filename){
    if (filename == null) {
        return -1;
    }
    int dotIndex = filename.lastIndexOf('.');
    if (dotIndex == -1) {
        return -1;
    }
    // Find the last directory separator (handling both '/' and '\')
    int slashIndex = Math.max(filename.lastIndexOf('/'), filename.lastIndexOf('\\'));
    // If a separator occurs after the last dot, the dot is part of the path, not the filename
    if (slashIndex >= dotIndex) {
        return -1;
    }
    return dotIndex;
}

public boolean isExpired(long timestamp, long expiredThreshold) {
    try {
        // An invalid threshold implies nothing should expire.
        if (expiredThreshold <= 0) {
            return false;
        }

        // Negative timestamps are considered invalid, treat as not expired.
        if (timestamp < 0) {
            return false;
        }

        long currentTime = System.currentTimeMillis();
        // If the timestamp is from the future, it cannot be expired yet.
        if (timestamp > currentTime) {
            return false;
        }

        return (currentTime - timestamp) > expiredThreshold;
    } catch (Exception e) {
        // In case of any unexpected failure, conservatively consider the metric expired.
        return true;
    }
}

