public static boolean substringMatch(CharSequence str, int index, CharSequence substring) {
    if (str == null || substring == null) {
        return false;
    }
    int subLen = substring.length();
    int strLen = str.length();
    if (subLen == 0) {
        // An empty substring matches any position from 0 to strLen (inclusive)
        return index >= 0 && index <= strLen;
    }
    if (index < 0 || index > strLen) {
        return false;
    }
    if (index + subLen > strLen) {
        return false;
    }
    try {
        for (int i = 0; i < subLen; i++) {
            if (str.charAt(index + i) != substring.charAt(i)) {
                return false;
            }
        }
        return true;
    } catch (Throwable t) {
        // Any runtime exception (e.g., IndexOutOfBounds) results in false
        return false;
    }
}

protected void append(LoggingEvent event) {
    // Guard against null events
    if (event == null) {
        return;
    }

    // Retrieve the rendered message.  Some LoggingEvent implementations may throw
    // an exception, so we catch it and use a fallback value.
    String message;
    try {
        message = event.getRenderedMessage();
    } catch (Exception e) {
        message = "[Unable to render log event]";
    }
    if (message == null) {
        message = "";
    }

    // Iterate over the connected clients in a thread‑safe manner.
    // It is assumed that the field 'clients' is a mutable collection that
    // holds objects with a write/flush capability (e.g. ClientHandler).
    // Adjust the field name and method names to match your actual implementation.
    synchronized (clients) {
        java.util.Iterator<ClientHandler> it = clients.iterator();
        while (it.hasNext()) {
            ClientHandler client = it.next();
            try {
                client.writeMessage(message);
            } catch (java.io.IOException ioe) {
                // If writing fails, remove the client to avoid future attempts.
                it.remove();
                // Attempt to close the client cleanly.
                try {
                    client.close();
                } catch (java.io.IOException ignored) {}
            } catch (Exception e) {
                // Catch any other unexpected exception so that logging does not
                // terminate prematurely.
                // Optionally, log this exception internally if you have a logger.
            }
        }
    }
}

