private void checkIfPackedField() throws IOException {
    // The current field is represented by the tag value that has already
    // been read into the class field `currentTag`.  If the wire type of this tag
    // is LENGTH_DELIMITED and the field number matches the known packed field
    // number, we will treat it as a packed field.
    //
    // Packed fields are encoded as a length-delimited block containing a
    // series of sub-elements (typically numeric).  To properly parse such a
    // block we need to:
    //   1. mark that we are currently reading a packed field,
    //   2. read the length of the packed data, and
    //   3. adjust the input limit so that subsequent reads stay within this
    //      block.  The original limit is saved so it can be restored by the
    //      caller when finished with the packed field.
    //
    // The following code assumes the presence of the following fields/methods
    // in the surrounding class:
    //   - int currentTag;                 // the last read tag
    //   - int packedFieldNumber;          // field number that may be packed
    //   - boolean isPacked;               // flag used to mark packed state
    //   - int packedElementLength;        // length of the packed element block
    //   - int oldLimit;                   // to restore after processing
    //   - static final int WIRETYPE_LENGTH_DELIMITED = 2; // protobuf constant
    //   - int readRawVarint32() throws IOException;         // read varint
    //   - int pushLimit(int newLimit) throws IOException;   // set new limit, return previous

    if (currentTag == 0) {
        // No tag has been read yet; nothing to do.
        return;
    }

    int fieldNumber = WireFormat.getTagFieldNumber(currentTag);
    int wireType = WireFormat.getTagWireType(currentTag);

    if (wireType == WireFormat.WIRETYPE_LENGTH_DELIMITED
            && fieldNumber == packedFieldNumber) {
        // Switch to packed mode.
        isPacked = true;
        // The next integer encodes the length of the packed block.
        packedElementLength = readRawVarint32();
        if (packedElementLength < 0) {
            throw new IOException("Negative packed field length");
        }
        // Push a new limit so that reads are confined to the packed block.
        oldLimit = pushLimit(packedElementLength);
    } else {
        // Not a packed field; no state changes required.
        // The caller can handle the field normally.
    }
}

public int readTag() throws IOException {
    if (isAtEnd()) {
        return 0;
    }
    int tag = readRawVarint32();
    if (tag == 0) {
        throw new IOException("Invalid tag number: 0");
    }
    return tag;
}

