private String buildContentRange(){
    try {
        long start = this.rangeStart;
        long end   = this.rangeEnd;
        long total = this.contentLength;
        if (total < 0) {
            // The total length is unknown; use a wildcard for the length
            return "bytes " + start + "-" + end + "/*";
        }
        // All values are known
        if (start >= 0 && end >= 0) {
            if (start > end) {
                throw new IllegalArgumentException("Range start (" + start + ") cannot be greater than range end (" + end + ").");
            }
            return "bytes " + start + "-" + end + "/" + total;
        }
        // Partial information is present
        if (start >= 0) {
            return "bytes " + start + "-*/" + total;
        }
        if (end >= 0) {
            return "bytes */" + total;
        }
        // If no range information, just return the total length
        return "bytes */" + total;
    } catch (Exception e) {
        // In case of any unexpected error, return null to indicate failure
        return null;
    }
}

public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    if (file == null) {
        throw new NullPointerException("file must not be null");
    }
    if (!file.exists() || !file.isFile()) {
        throw new FileNotFoundException("The specified file does not exist or is not a regular file: " + file.getPath());
    }

    List<ThreadSnapshot> result = new ArrayList<>();
    boolean filter = timeRanges != null && !timeRanges.isEmpty();

    try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
        String line;
        while ((line = reader.readLine()) != null) {
            line = line.trim();
            if (line.isEmpty()) {
                continue;
            }

            ThreadSnapshot snapshot;
            try {
                snapshot = ThreadSnapshot.fromString(line);
            } catch (Exception e) {
                // If parsing fails for a particular line, skip it but continue processing the rest
                continue;
            }

            if (!filter) {
                result.add(snapshot);
            } else {
                long ts = snapshot.getTimestamp(); // Assuming ThreadSnapshot has getTimestamp()
                for (ProfileAnalyzeTimeRange range : timeRanges) {
                    if (ts >= range.getStartTime() && ts <= range.getEndTime()) {
                        result.add(snapshot);
                        break;
                    }
                }
            }
        }
    }

    return result;
}
